INSERT INTO TBL_ESTIMATE_RULE (RULE_KEY, RULE_VALUE, BASIS_NOTE) VALUES ('적재계수', 2.0, '물품 기준 부피 합 × 이 값 = 트럭 적재 부피. 포장재·빈 공간·서랍과 수납장에서 꺼낸 짐 포함. 근거 2가지가 거의 같음: ① 바구니(55×40×35cm=0.077 CBM)가 1톤(10 CBM)에 50~70개 → 개당 0.14~0.2 CBM으로 약 2배 ② 우리 집 정답 목록 물품 부피 약 26 CBM + 표에 없는 소품 → 대표님 견적 55 CBM, 약 2배 [표본 1집, 영상 더 모으면 다시 맞춤]');
INSERT INTO TBL_ESTIMATE_RULE (RULE_KEY, RULE_VALUE, BASIS_NOTE) VALUES ('계약금비율', 10, '대표님: 계약금은 이사 비용의 10%');
INSERT INTO TBL_ESTIMATE_RULE (RULE_KEY, RULE_VALUE, BASIS_NOTE) VALUES ('별도비용최소', 200000, '대표님: 사다리차를 못 대고 짐을 50~200m 날라야 하는 등 여건이 어려우면 20만~50만 원 별도');
INSERT INTO TBL_ESTIMATE_RULE (RULE_KEY, RULE_VALUE, BASIS_NOTE) VALUES ('별도비용최대', 500000, '위와 같음. 금액을 넣지 않고 안내 문구로만 표시');
INSERT INTO TBL_ESTIMATE_RULE (RULE_KEY, RULE_VALUE, BASIS_NOTE) VALUES ('보관배수최소', 1.5, '아정당: 보관이사 = 포장이사 비용 × 1.5~2배 (짐을 창고에 넣고 다시 빼는 두 번 작업)');
INSERT INTO TBL_ESTIMATE_RULE (RULE_KEY, RULE_VALUE, BASIS_NOTE) VALUES ('보관배수최대', 2.0, '위와 같음');
